  &DefaultButton;




function dir$lscuocgoi(p){
  this.constructor(p);
}
dir$lscuocgoi.prototype = new DirEvent();
dir$lscuocgoi.prototype.afterInit = function(){
  var p = this._dir;
}
dir$lscuocgoi.prototype.afterInit = function(renderType){
  var p = this._dir,g = p.grid()

dir$lscuocgoiDisabledMasterField(p, g);

}

function dir$lscuocgoiDisabledMasterField(p, g){

  if(p.valForm('ma_so_thue').trim() != '')
  {
    p.setDisabled('ma_so_thue', true);
  }
  else
  {
    p.setDisabled('ma_so_thue', false);
  }
}






	.control-label.ma_so_thue, .control-label.ngay_goi
	{	
		//font-weight:bold;	
		color: #499b98;;
	}







if @action = 'EDIT' begin
&CheckUpdatingDeleting;
end
select @@fields into #@@table from @@table a where [%whereFieldKey]
[%updateRef]
select * from #@@table

declare @script nvarchar(4000)
select @script = '';
if @action = 'EDIT'
  if exists(select 1 from syscodeexists with(nolock, index(code1)) where code1 = @uniqueid and field = 'uniqueid')
    select @script = @script + 'p.setDisabled(''uniqueid'', true); '

if @action in ('EDIT', 'VIEW') select @script as script
drop table #@@table





        &CheckUpdatingDeleting;







